const TYPES = [
  'Purchase',
  'Sales',
  'Receipt',
  'Payment',
  'Debit Note',
  'Credit Note',
  'Contra',
  'Journal',
] as const;

function voucher(type: string, index: number): string {
  const inventory = type === 'Sales'
    ? `<ALLINVENTORYENTRIES.LIST>
        <STOCKITEMNAME>Fixture Item</STOCKITEMNAME>
        <ACTUALQTY>2 PCS</ACTUALQTY>
        <BILLEDQTY>2 PCS</BILLEDQTY>
        <RATE>50/PCS</RATE>
        <AMOUNT>100.00</AMOUNT>
        <ACCOUNTINGALLOCATIONS.LIST><LEDGERNAME>Sales</LEDGERNAME><AMOUNT>100.00</AMOUNT></ACCOUNTINGALLOCATIONS.LIST>
        <BATCHALLOCATIONS.LIST><GODOWNNAME>Main</GODOWNNAME><BATCHNAME>Primary</BATCHNAME></BATCHALLOCATIONS.LIST>
        <INVENTORYALLOCATIONS.LIST><STOCKITEMNAME>Fixture Item</STOCKITEMNAME><AMOUNT>100.00</AMOUNT></INVENTORYALLOCATIONS.LIST>
      </ALLINVENTORYENTRIES.LIST>`
    : '';
  const ledgerAllocations = type === 'Sales'
    ? `<BILLALLOCATIONS.LIST><NAME>Bill-1</NAME><BILLTYPE>New Ref</BILLTYPE></BILLALLOCATIONS.LIST>
       <BANKALLOCATIONS.LIST><TRANSACTIONTYPE>Cheque</TRANSACTIONTYPE></BANKALLOCATIONS.LIST>
       <COSTTRACKALLOCATIONS.LIST><NAME>Project-1</NAME></COSTTRACKALLOCATIONS.LIST>`
    : '';
  return `<VOUCHER>
    <DATE>20260727</DATE>
    <EFFECTIVEDATE>20260727</EFFECTIVEDATE>
    <GUID>fixture-guid-${index}</GUID>
    <MASTERID>${index}</MASTERID>
    <ALTERID>${index + 100}</ALTERID>
    <VOUCHERKEY>fixture-key-${index}</VOUCHERKEY>
    <VOUCHERRETAINKEY>fixture-retain-${index}</VOUCHERRETAINKEY>
    <VOUCHERTYPENAME>${type}</VOUCHERTYPENAME>
    <VOUCHERNUMBER>${index}</VOUCHERNUMBER>
    <REFERENCE>Reference-${index}</REFERENCE>
    <NARRATION>Fixture narration ${index}</NARRATION>
    <PARTYLEDGERNAME>Fixture Party</PARTYLEDGERNAME>
    <AMOUNT>-100.00</AMOUNT>
    <ISCANCELLED>${type === 'Credit Note' ? 'Yes' : 'No'}</ISCANCELLED>
    <ALLLEDGERENTRIES.LIST>
      <LEDGERNAME>Fixture Ledger</LEDGERNAME>
      <AMOUNT>-100.00</AMOUNT>
      <ISDEEMEDPOSITIVE>Yes</ISDEEMEDPOSITIVE>
      ${ledgerAllocations}
    </ALLLEDGERENTRIES.LIST>
    ${inventory}
  </VOUCHER>`;
}

export const APPROVED_VOUCHER_FIXTURE_XML = `<ENVELOPE>
  <HEADER><STATUS>1</STATUS></HEADER>
  <BODY>
    <DESC><CMPINFO><VOUCHER>8</VOUCHER></CMPINFO></DESC>
    <DATA><COLLECTION>${TYPES.map((type, index) => voucher(type, index + 1)).join('')}</COLLECTION></DATA>
  </BODY>
</ENVELOPE>`;

